const results = [];
const R = (id, held, note) => { results.push({ id, held }); console.log(
  `${held ? "CONFINED" : "BREACH  "}  ${id.padEnd(26)} ${note}`); };

/* ── DERIVE-v0.2.0 identity and evaluation, VERBATIM ──────────────────────
